package com.secman.controller

import com.secman.domain.Requirement
import com.secman.repository.RequirementRepository
import com.secman.repository.UseCaseRepository
import com.secman.service.RequirementWordContentRenderer
import com.secman.service.WordExportStyle
import io.micronaut.core.annotation.Nullable
import io.micronaut.http.HttpResponse
import io.micronaut.http.MediaType
import io.micronaut.http.annotation.*
import io.micronaut.http.server.types.files.StreamedFile
import io.micronaut.security.annotation.Secured
import io.micronaut.security.rules.SecurityRule
import io.micronaut.serde.annotation.Serdeable
import org.apache.poi.xwpf.usermodel.BreakType
import org.apache.poi.xwpf.usermodel.ParagraphAlignment
import org.apache.poi.xwpf.usermodel.XWPFDocument
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

@Controller("/api/reqdl")
@Secured(SecurityRule.IS_ANONYMOUS)
open class PublicRequirementDownloadController(
    private val requirementRepository: RequirementRepository,
    private val useCaseRepository: UseCaseRepository
) {

    @Serdeable
    data class UseCaseDto(val id: Long, val name: String)

    @Get("/usecases")
    fun listUseCases(): HttpResponse<List<UseCaseDto>> {
        val useCases = useCaseRepository.findAll()
            .map { UseCaseDto(it.id!!, it.name) }
            .sortedBy { it.name }
        return HttpResponse.ok(useCases)
    }

    @Get("/export/docx")
    fun exportToDocx(@Nullable @QueryValue("usecaseIds") usecaseIds: String?): HttpResponse<*> {
        val requirements: List<Requirement>
        val title: String
        val filenameSuffix: String

        if (!usecaseIds.isNullOrBlank()) {
            val ids = usecaseIds.split(",").mapNotNull { it.trim().toLongOrNull() }
            if (ids.isEmpty()) {
                return HttpResponse.badRequest(mapOf("error" to "Invalid use case IDs"))
            }

            val useCases = ids.mapNotNull { id -> useCaseRepository.findById(id).orElse(null) }
            if (useCases.isEmpty()) {
                return HttpResponse.notFound(mapOf("error" to "No valid use cases found"))
            }

            val useCaseNames = useCases.map { it.name }

            // Get requirements that have at least one of the selected use cases
            val reqSet = mutableSetOf<Long>()
            val allReqs = mutableListOf<Requirement>()
            for (id in ids) {
                for (req in requirementRepository.findByUsecaseId(id)) {
                    if (reqSet.add(req.id!!)) {
                        allReqs.add(req)
                    }
                }
            }

            requirements = allReqs.sortedWith(
                compareBy<Requirement> { it.chapter ?: "" }.thenBy { it.id ?: 0 }
            )
            title = "Requirements - ${useCaseNames.joinToString(", ")}"
            filenameSuffix = "_${useCaseNames.joinToString("_") { it.replace(" ", "") }}"
        } else {
            requirements = requirementRepository.findAll().sortedWith(
                compareBy<Requirement> { it.chapter ?: "" }.thenBy { it.id ?: 0 }
            )
            title = "All Requirements"
            filenameSuffix = ""
        }

        if (requirements.isEmpty()) {
            return HttpResponse.ok(mapOf("message" to "No requirements found"))
        }

        val document = createWordDocument(requirements, title)
        val outputStream = ByteArrayOutputStream()

            // Delete all requirements (cascade will handle join-table relationships)
            requirementRepository.deleteAll()
            // Delete all standards/norms too, now that no requirement references them
            normRepository.deleteAll()
            // Reset the REQ-NNN sequence so the next imported requirement starts at REQ-001
            requirementIdService.resetSequence()

            return HttpResponse.ok(mapOf(
                "message" to "All requirements and standards deleted successfully",
                "deletedCount" to requirementCount,
                "deletedRequirements" to requirementCount,
                "deletedNorms" to normCount
            ))
        } catch (e: Exception) {
            return HttpResponse.serverError<Any>().body(mapOf("error" to "An internal error occurred"))
        }
    }

    /**
     * Public requirement export as Word.
     *
     * Scope is chosen by four optional query parameters, all of which also apply to
     * `/export/xlsx`:
     * - `standardId` / `standard` — narrow to one standard's use cases (id wins if both given)
     * - `releaseId` / `release` — freeze to a release; `release=latest` means the ACTIVE one
     *
     * With none of them the response is unchanged: every live requirement.
     * See `docs/PUBLIC_STANDARD_DOWNLOAD.md`.
     */
    @Get("/export/docx")
    @Secured(SecurityRule.IS_ANONYMOUS) // Public: powers the unauthenticated /requirements/download page
    fun exportToDocx(
        @Nullable @QueryValue("releaseId") releaseId: Long?,
        @Nullable @QueryValue("release") release: String?,
        @Nullable @QueryValue("standardId") standardId: Long?,
        @Nullable @QueryValue("standard") standard: String?,
        @QueryValue(defaultValue = "LATEST") templateMode: String,
        @Nullable @QueryValue("templateId") templateId: Long?,
        @QueryValue(defaultValue = "REJECT") missingPlaceholderBehavior: String,
        @Nullable @QueryValue("classification") classification: String?,
        @Nullable authentication: Authentication?
    ): HttpResponse<*> {
        val scope = when (val resolution =
            standardExportScopeService.resolve(standardId, standard, releaseId, release)) {
            is StandardExportScopeService.Resolution.Invalid ->
                return HttpResponse.badRequest(mapOf("error" to resolution.message))
            is StandardExportScopeService.Resolution.Missing ->
                return HttpResponse.notFound(mapOf("error" to resolution.message))
            is StandardExportScopeService.Resolution.Resolved -> resolution
        }

        val exportData = buildRequirementExportData(scope.release, scope.standard, "docx")
        if (scope.standard != null && exportData.requirements.isEmpty()) {
            return HttpResponse.ok(mapOf("message" to "No requirements found for this standard"))
        }

        logPublicExport("docx", scope, exportData.requirements.size, authentication)

        return exportWordDocument(
            requirements = exportData.requirements,
            title = exportData.title,
            filename = exportData.filename,
            templateMode = templateMode,
            templateId = templateId,
            adHocTemplate = null,
            missingPlaceholderBehavior = missingPlaceholderBehavior,
            classification = classification,
            language = null,
            scope = exportScopeOf(scope),
            releaseId = scope.release?.id,
            usecaseId = null,
            authentication = authentication,
            release = exportData.release
        )
    }

    @Post("/export/docx")
    @Consumes(MediaType.MULTIPART_FORM_DATA)
    fun exportToDocxWithAdHocTemplate(
        @Nullable @QueryValue("releaseId") releaseId: Long?,
        @Part templateFile: CompletedFileUpload,
        @Nullable @Part templateMode: String?,
        @Nullable @Part missingPlaceholderBehavior: String?,
        @Nullable @Part classification: String?,
        authentication: Authentication
    ): HttpResponse<*> {
        val exportData = resolveRequirementExportData(releaseId)
            ?: return HttpResponse.notFound(mapOf("error" to "Release not found"))

        return exportWordDocument(
            requirements = exportData.requirements,
            title = exportData.title,
            filename = exportData.filename,
            templateMode = templateMode ?: "ADHOC",
            templateId = null,
            adHocTemplate = templateFile,
            missingPlaceholderBehavior = missingPlaceholderBehavior ?: "REJECT",
            classification = classification,
            language = null,
            scope = if (releaseId != null) RequirementExportScope.RELEASE else RequirementExportScope.ALL,
            releaseId = releaseId,
            usecaseId = null,
            authentication = authentication,
            release = exportData.release
        )
    }

    @Get("/export/docx/usecase/{usecaseId}")
    @Secured(SecurityRule.IS_ANONYMOUS) // Public: powers the unauthenticated /requirements/download page
    fun exportToDocxByUseCase(
        @PathVariable usecaseId: Long,
        @Nullable @QueryValue("releaseId") releaseId: Long?,
        @QueryValue(defaultValue = "LATEST") templateMode: String,
        @Nullable @QueryValue("templateId") templateId: Long?,
        @QueryValue(defaultValue = "REJECT") missingPlaceholderBehavior: String,
        @Nullable @QueryValue("classification") classification: String?,
        @Nullable authentication: Authentication?
    ): HttpResponse<*> {
        val useCaseOptional = useCaseRepository.findById(usecaseId)

        if (useCaseOptional.isEmpty) {
            return HttpResponse.notFound<Any>().body(mapOf("error" to "UseCase not found"))
        }

        val useCase = useCaseOptional.get()
        val requirements = getRequirementsByUseCase(usecaseId, releaseId)

        if (requirements.isEmpty()) {
            return HttpResponse.ok(mapOf("message" to "No requirements found for this use case"))
        }

        val filename = "requirements_usecase_${useCase.name.replace(" ", "_")}.docx"
            .replace("\"", "").replace("\r", "").replace("\n", "")

        return exportWordDocument(
            requirements = requirements,
            title = "Requirements for UseCase: ${useCase.name}",
            filename = filename,
            templateMode = templateMode,
            templateId = templateId,
            adHocTemplate = null,
            missingPlaceholderBehavior = missingPlaceholderBehavior,
            classification = classification,
            language = null,
            scope = RequirementExportScope.USE_CASE,
            releaseId = releaseId,
            usecaseId = usecaseId,
            authentication = authentication,
            release = releaseId?.let { releaseRepository.findById(it).orElse(null) },
            useCase = useCase
        )
    }

    @Post("/export/docx/usecase/{usecaseId}")
    @Consumes(MediaType.MULTIPART_FORM_DATA)
    fun exportToDocxByUseCaseWithAdHocTemplate(
        @PathVariable usecaseId: Long,
        @Nullable @QueryValue("releaseId") releaseId: Long?,
        @Part templateFile: CompletedFileUpload,
        @Nullable @Part templateMode: String?,
        @Nullable @Part missingPlaceholderBehavior: String?,
        @Nullable @Part classification: String?,
        authentication: Authentication
    ): HttpResponse<*> {
        val useCaseOptional = useCaseRepository.findById(usecaseId)
        if (useCaseOptional.isEmpty) {
            return HttpResponse.notFound<Any>().body(mapOf("error" to "UseCase not found"))
        }
        val useCase = useCaseOptional.get()
        val requirements = getRequirementsByUseCase(usecaseId, releaseId)
        if (requirements.isEmpty()) {
            return HttpResponse.ok(mapOf("message" to "No requirements found for this use case"))
        }
        val filename = "requirements_usecase_${useCase.name.replace(" ", "_")}.docx"
            .replace("\"", "").replace("\r", "").replace("\n", "")

        return exportWordDocument(
            requirements = requirements,
            title = "Requirements for UseCase: ${useCase.name}",
            filename = filename,
            templateMode = templateMode ?: "ADHOC",
            templateId = null,
            adHocTemplate = templateFile,
            missingPlaceholderBehavior = missingPlaceholderBehavior ?: "REJECT",
            classification = classification,
            language = null,
            scope = RequirementExportScope.USE_CASE,
            releaseId = releaseId,
            usecaseId = usecaseId,
            authentication = authentication,
            release = releaseId?.let { releaseRepository.findById(it).orElse(null) },
            useCase = useCase
        )
    }

    /** Public requirement export as Excel. Same scope parameters as [exportToDocx]. */
    @Get("/export/xlsx")
    @Secured(SecurityRule.IS_ANONYMOUS) // Public: powers the unauthenticated /requirements/download page
    fun exportToExcel(
        @Nullable @QueryValue("releaseId") releaseId: Long?,
        @Nullable @QueryValue("release") release: String?,
        @Nullable @QueryValue("standardId") standardId: Long?,
        @Nullable @QueryValue("standard") standard: String?,
        @Nullable authentication: Authentication?
    ): HttpResponse<*> {
        val scope = when (val resolution =
            standardExportScopeService.resolve(standardId, standard, releaseId, release)) {
            is StandardExportScopeService.Resolution.Invalid ->
                return HttpResponse.badRequest(mapOf("error" to resolution.message))
            is StandardExportScopeService.Resolution.Missing ->
                return HttpResponse.notFound(mapOf("error" to resolution.message))
            is StandardExportScopeService.Resolution.Resolved -> resolution
        }

        val exportData = buildRequirementExportData(scope.release, scope.standard, "xlsx")
        if (scope.standard != null && exportData.requirements.isEmpty()) {
            return HttpResponse.ok(mapOf("message" to "No requirements found for this standard"))
        }

        logPublicExport("xlsx", scope, exportData.requirements.size, authentication)

        val workbook = createExcelWorkbook(exportData.requirements)
        val outputStream = ByteArrayOutputStream()
        workbook.write(outputStream)
        workbook.close()

        val inputStream = ByteArrayInputStream(outputStream.toByteArray())
        // Same header hygiene as streamWordDocument: the release version reaches this name.
        val filename = exportData.filename.replace("\"", "").replace("\r", "").replace("\n", "")

        return HttpResponse.ok(StreamedFile(inputStream, MediaType.of("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")))
            .header("Content-Disposition", "attachment; filename=\"$filename\"")
    }

    @Get("/export/xlsx/usecase/{usecaseId}")
    @Secured(SecurityRule.IS_ANONYMOUS) // Public: powers the unauthenticated /requirements/download page
    fun exportToExcelByUseCase(@PathVariable usecaseId: Long, @Nullable @QueryValue("releaseId") releaseId: Long?): HttpResponse<*> {
        val useCaseOptional = useCaseRepository.findById(usecaseId)

        if (useCaseOptional.isEmpty) {
            return HttpResponse.notFound<Any>().body(mapOf("error" to "UseCase not found"))
        }

        val useCase = useCaseOptional.get()
        val requirements = getRequirementsByUseCase(usecaseId, releaseId)

        if (requirements.isEmpty()) {
            return HttpResponse.ok(mapOf("message" to "No requirements found for this use case"))
        }

        val workbook = createExcelWorkbook(requirements)
        val outputStream = ByteArrayOutputStream()
        workbook.write(outputStream)
        workbook.close()

        val inputStream = ByteArrayInputStream(outputStream.toByteArray())
        val filename = "requirements_usecase_${useCase.name.replace(" ", "_")}.xlsx"
            .replace("\"", "").replace("\r", "").replace("\n", "")

        return HttpResponse.ok(StreamedFile(inputStream, MediaType.of("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")))
            .header("Content-Disposition", "attachment; filename=\"$filename\"")
    }


    private data class RequirementExportData(
        val requirements: List<Requirement>,
        val filename: String,
        val title: String,
        /**
         * The release the export was frozen against, when one was selected. Carried as the entity
         * rather than re-derived from [title] so the template placeholders bind to real metadata.
         */
        val release: Release? = null,
        /** The use case the export was narrowed to, when one was selected. */
        val useCase: UseCase? = null
    )

    private data class ResolvedTemplate(
        val mode: RequirementExportTemplateMode,
        val savedTemplate: RequirementExportTemplate?,
